function nxChangeType($title){$t=strtolower(trim($title));if(preg_match('/^(feat|add|added|new)(\([^)]*\))?:?/',$t))return ['Tilføjet','fa-plus','added'];if(preg_match('/^(fix|fixed|bugfix|repair)(\([^)]*\))?:?/',$t))return ['Repareret','fa-wrench','fixed'];if(preg_match('/^(remove|removed|delete|deleted)(\([^)]*\))?:?/',$t))return ['Fjernet','fa-trash','removed'];if(preg_match('/^(change|changed|update|updated|refactor)(\([^)]*\))?:?/',$t))return ['Ændret','fa-refresh','changed'];if(preg_match('/^(security|secure)(\([^)]*\))?:?/',$t))return ['Sikkerhed','fa-shield','security'];if(preg_match('/^(perf|performance|optimize)(\([^)]*\))?:?/',$t))return ['Forbedret','fa-bolt','improved'];return ['Ændret','fa-code','changed'];}
@endphp
