ont-size:9px;font-weight:850;letter-spacing:.07em;text-transform:uppercase;margin-bottom:5px}.nu-tag.added{background:rgba(72,214,154,.1);color:#55dda5}.nu-tag.fixed{background:rgba(64,153,255,.1);color:#6aafff}.nu-tag.removed{background:rgba(246,83,98,.1);color:#ff7e8a}.nu-tag.changed{background:rgba(116,92,255,.1);color:#aaa0ff}.nu-tag.security{background:rgba(245,184,70,.1);color:#f5c46b}.nu-tag.improved{background:rgba(42,204,220,.1);color:#5adbe8}.nu-change-meta{font-size:10px;color:#727c8f;text-align:right;white-space:nowrap}.nu-sha{display:block;color:#aaa0ff;margin-top:4px}.nu-empty{padding:35px;text-align:center;color:var(--m)}.nu-info{padding:19px}.nu-row{padding:13px 0;border-bottom:1px solid var(--line)}.nu-row:last-child{border:0}.nu-row span{display:block;color:var(--m);font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;margin-bottom:5px}.nu-row code{background:rgba(116,92,255,.09);color:#b4abff;border-radius:5px;padding:3px 6px}.nu-safe{margin-top:15px;padding:13px;border-radius:10px;background:rgba(72,214,154,.055);border:1px solid rgba(72,214,154,.13);color:#9fb9ae;font-size:12px;line-height:1.5}.nu-flash{border-radius:10px;padding:12px 15px;margin-bottom:15px}.nu-flash.ok{background:rgba(72,214,154,.08);color:#67dfa9}.nu-flash.bad{background:rgba(246,83,98,.08);color:#ff8994}@media(max-width:850px){.nu-layout{grid-template-columns:1fr}.nu-top,.nu-pagehead{flex-direction:column;align-items:flex-start}.nu-actions{width:100%}.nu-actions>*{flex:1}.nu-versions{grid-template-columns:1fr}.nu-arrow{transform:rotate(90deg);justify-self:center}.nu-ver:last-child{justify-content:flex-start;text-align:left}}@media(max-width:520px){.nu-hero{padding:20px}.nu-actions{flex-direction:column}.nu-change{grid-template-columns:38px 1fr}.nu-change-meta{grid-column:2;text-align:left}}
