<script>(function(){var url=@json(route('admin.updates.status')),seen=@json(($state['status']??'')==='running'),reload=false;function btn(b,a,r){if(!b)return;var i=b.querySelector('i'),t=document.getElementById('nodexa-update-button-text');b.disabled=r||!a;if(i)i.className=r?'fa fa-spinner fa-spin':(a?'fa fa-arrow-down':'fa fa-check');if(t)t.textContent=r?'Installerer…':(a?'Installer update':'Opdateret')}function poll(){fetch(url,{headers:{Accept:'application/json'},credentials:'same-origin'}).then(r=>r.json()).then(d=>{var s=d.state||{},a=d.update_available===true,time=document.getElementById('nodexa-update-time'),b=document.getElementById('nodexa-update-button'),title=document.getElementById('nuTitle'),msg=document.getElementById('nuMessage'),head=document.getElementById('nuHeadText'),p=document.getElementById('nuProgress'),icon=document.querySelector('#nuIcon i');if(time)time.textContent=s.updated_at||'Ingen aktivitet endnu';if(s.status==='running'){seen=true;title.textContent='Installerer opdatering…';msg.textContent=s.message||'Nodexa opdateres automatisk.';head.textContent='Opdaterer nu';p.classList.add('show');icon.className='fa fa-refresh fa-spin';btn(b,a,true);return}p.classList.remove('show');if(s.status==='failed'&&seen){title.textContent='Opdateringen fejlede';msg.textContent=s.message||'Opdateringen kunne ikke gennemføres.';head.textContent='Update fejlede';icon.className='fa fa-times';btn(b,a,false);return}if(s.status==='success'&&seen){title.textContent='Nodexa er opdateret';msg.textContent='Den nye version er installeret.';head.textContent='Update installeret';icon.className='fa fa-check';btn(b,false,false);if(!reload){reload=true;setTimeout(()=>location.reload(),2200)}return}title.textContent=a?'En ny version er klar':'Du kører den nyeste version';msg.textContent=a?'Installer den nyeste Nodexa-version. Konfiguration og serverdata bevares.':'Der er ingen nyere version tilgængelig på den valgte branch.';head.textContent=a?'Ny version tilgængelig':'Nodexa er opdateret';icon.className=a?'fa fa-arrow-down':'fa fa-check';btn(b,a,false)}).catch(()=>{})}setInterval(poll,2200);poll()})();</script>
